hl.window_rule({
    match = {
        class = ".*",
    },
    suppress_event = "maximize",
})

hl.window_rule({
    match = {
        class = "^$",
        title = "^$",
        xwayland = 1,
        float = 1,
        fullscreen = 0,
        pin = 0,
    },
    no_focus = true,
})

hl.window_rule({
    match = {
        initial_title = "(Discord Popout)",
    },
    float = true,
    pin = true,
})

hl.window_rule({
    match = {
        title = "(Picture in Picture)",
    },
    float = true,
    pin = true,
})

hl.window_rule({
    match = {
        title = "(Picture-in-Picture)",
    },
    float = true,
    pin = true,
})

hl.window_rule({
    match = {
        title = "(Steam Settings)",
    },
    float = true,
})

